/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var format = require( '@stdlib/string/format' );
var isValidForegroundColor = require( './../../utils/is-valid-foreground-color.js' );


// MAIN //

/**
* Set forground color.
*
* @private
* @param {string} value - string indicating color name
* @throws {TypeError} must be a valid forground color code
*/
function set( value ) {
	if ( !isString( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a string. Value: `%s`.', 'forground-color', value ) );
	}
	if ( !isValidForegroundColor( value ) ) {
		throw new TypeError( format( 'invalid value, `%s` must be a valid forground color code. Value: `%s`.', 'forground-color', value ) );
	}
	if ( this._foregroundColor !== value ) {
		this._foregroundColor = value;
		if ( !this._quite ) {
			this.emit( 'change' );
		}
	}
}


// EXPORTS //

module.exports = set;
